class View:
    def __init__(self):
        self.rows=[]; self.notes={}; self.loading=False; self.error=None; self.seq=0; self.last_req=None
    def begin(self, query):
        self.seq+=1; self.last_req=self.seq; self.loading=True; self.error=None
        return self.seq
    def finish(self, request_id, rows, notes=None):
        if self.last_req!=request_id: return False
        self.rows=rows[:]; self.loading=False; self.notes=notes if notes is not None else self.notes
        return True
